namespace PatientManagement.Core.DTOs.Ai;

public static class AiSafetyConstants
{
    public const string ClinicalDisclaimer =
        "AI Clinical Decision Support Only: This output is generated by an automated assistant and must be reviewed and verified by a licensed clinician before making clinical or scheduling decisions.";

    public const string SimulatedModeBanner =
        "SIMULATED MODE ACTIVE: No live Gemini API key is configured on the server. Output below is deterministic demo output and NOT real AI clinical analysis.";
}

public class PendingActionProposalDto
{
    public string ActionId { get; set; } = string.Empty;
    public string ActionType { get; set; } = "ScheduleConsultation";
    public string ConfirmationPrompt { get; set; } = string.Empty;
    public int PatientId { get; set; }
    public int? DoctorId { get; set; }
    public string DoctorName { get; set; } = string.Empty;
    public DateTime ProposedDateUtc { get; set; }
    public int DurationMinutes { get; set; } = 30;
    public string DiagnosisOrReason { get; set; } = string.Empty;
    public string Status { get; set; } = "Pending";
    public DateTime ExpiresAtUtc { get; set; }
}

public class AiSourceCitationDto
{
    public int ConsultationId { get; set; }
    public DateTime ConsultationDate { get; set; }
    public string DoctorName { get; set; } = string.Empty;
    public string ClinicalSnippet { get; set; } = string.Empty;
    public string SourceType { get; set; } = "Consultation"; // "Consultation", "PatientDocument"
    public int? DocumentId { get; set; }
    public string? DocumentName { get; set; }
    public int? ChunkIndex { get; set; }
    public double? SimilarityScore { get; set; }
    public double? RelevanceScore { get; set; }
    public bool IsCompressed { get; set; }
}

public class AiChatResponseDto
{
    public string SessionId { get; set; } = string.Empty;
    public string Reply { get; set; } = string.Empty;
    public List<string> ToolsExecuted { get; set; } = new();
    public List<PendingActionProposalDto> PendingActions { get; set; } = new();
    public List<AiSourceCitationDto> SourceCitations { get; set; } = new();
    public List<string> CollaboratingAgents { get; set; } = new();
    public List<string> PharmacovigilanceWarnings { get; set; } = new();
    public double? GroundingScore { get; set; }
    public bool IsGrounded { get; set; } = true;
    public bool WasSelfCorrected { get; set; }
    public List<ClinicalClaimVerification> VerifiedClaims { get; set; } = new();
    public object? ExtractedData { get; set; }
    public bool Success { get; set; } = true;
    public bool IsSimulatedMode { get; set; }
    public string? SimulatedModeNotice => IsSimulatedMode ? AiSafetyConstants.SimulatedModeBanner : null;
    public bool EmergencyRuleTriggered { get; set; }
    public string Disclaimer { get; set; } = AiSafetyConstants.ClinicalDisclaimer;
    public string? ModelUsed { get; set; }
    public DateTime Timestamp { get; set; } = DateTime.UtcNow;
}
